const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point(-96.111167, 29.956182);
  const geometry = point.buffer(4000); // 4km radius
  const scale = 30; // Landsat spatial resolution

  const date1_start = '2016-05-26'; // May 28, 2016 +/- 2 days
  const date1_end = '2016-05-30';
  const date2_start = '2013-05-02'; // May 4, 2013 +/- 2 days
  const date2_end = '2013-05-06';

  // Function to mask clouds from Landsat 8 SR data
  function maskL8sr(image) {
    // Bits 3 (cloud shadow), 5 (clouds), 7 (dilated cloud)
    const qa = image.select('QA_PIXEL');
    const cloudShadowBitMask = (1 << 3);
    const cloudsBitMask = (1 << 5);
    const dilatedCloudBitMask = (1 << 7);
    // Both flags should be set to 0, also filter out saturated pixels.
    const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                   .and(qa.bitwiseAnd(cloudsBitMask).eq(0))
                   .and(qa.bitwiseAnd(dilatedCloudBitMask).eq(0))
                   .and(image.select('SR_B2').lt(10000)); // Filter out some potential bad data
    return image.updateMask(mask).select('SR_B.');
  }

  // Function to calculate NDWI and create a water mask
  function calculateNdwi(image) {
    const ndwi = image.normalizedDifference(['SR_B3', 'SR_B5']).rename('NDWI');
    // A common threshold for water is NDWI > 0.
    // Given the question, we are looking for inundation, so a stricter threshold might be better.
    // Let's use 0.2, which is often used for open water.
    const waterMask = ndwi.gt(0.2).rename('water');
    return waterMask;
  }

  // 2. Data Acquisition & Check
  const collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_SR')
    .filterBounds(geometry);

  const col2016 = collection.filterDate(date1_start, date1_end)
    .map(maskL8sr)
    .sort('CLOUD_COVER') // Get the least cloudy image
    .first();

  const col2013 = collection.filterDate(date2_start, date2_end)
    .map(maskL8sr)
    .sort('CLOUD_COVER') // Get the least cloudy image
    .first();

  if (!col2016) {
    console.log("No valid Landsat 8 image found for 2016-05-28.");
    console.log("C1");
    return;
  }
  if (!col2013) {
    console.log("No valid Landsat 8 image found for 2013-05-04.");
    console.log("C1");
    return;
  }

  // Calculate NDWI water mask for each period
  const waterMask2016 = calculateNdwi(col2016);
  const waterMask2013 = calculateNdwi(col2013);

  // Calculate pixel count to detect C2
  const reducer = ee.Reducer.sum().unweighted(); // count of water pixels
  const areaReducer = ee.Reducer.sum();

  const waterPixels2016 = waterMask2016.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9,
  }).get('water').getInfo();

  const waterPixels2013 = waterMask2013.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: scale,
    maxPixels: 1e9,
  }).get('water').getInfo();

  if (waterPixels2016 === 0 || waterPixels2013 === 0) {
    console.log(`2016 Water Pixels (initial): ${waterPixels2016}, 2013 Water Pixels (initial): ${waterPixels2013}`);
    console.log("C2");
    return;
  }

  // 3. Calculate Inundation Area (in sq km)
  const inundationArea2016 = waterMask2016.multiply(ee.Image.pixelArea()).divide(1e6) // convert to sq km
    .reduceRegion({
      reducer: areaReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
    }).get('water').getInfo();

  const inundationArea2013 = waterMask2013.multiply(ee.Image.pixelArea()).divide(1e6) // convert to sq km
    .reduceRegion({
      reducer: areaReducer,
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
    }).get('water').getInfo();

  if (inundationArea2016 === null || inundationArea2013 === null || isNaN(inundationArea2016) || isNaN(inundationArea2013)) {
    console.log("Calculation of inundation area failed.");
    console.log("C3");
    return;
  }

  // 5. Validation & Final Answer
  console.log(`Inundation Area on 2013-05-04: ${inundationArea2013.toFixed(2)} sq km`);
  console.log(`Inundation Area on 2016-05-28: ${inundationArea2016.toFixed(2)} sq km`);
  console.log(`Total pixels for 2013 image: ${waterPixels2013}, for 2016 image: ${waterPixels2016}`);

  if (inundationArea2016 > inundationArea2013) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
